'use strict';

const DataClient = require('./client');
const RegistryBase = require('sofa-rpc-node/lib/registry/base');

class APIClient extends RegistryBase {
  get DataClient() {
    return DataClient;
  }

  get logger() {
    return this.options.logger;
  }

  get clusterOptions() {
    return {
      name: 'AntfinfConfigClient',
      transcode: require('./transcode'),
    };
  }

  get delegates() {
    return {
      unPublish: 'invokeOneway',
    };
  }

  subscribe(reg, listener) {
    this.changeReg(reg);
    this._client.subscribe(reg, listener);
    return this;
  }

  unSubscribe(reg, listener) {
    this.changeReg(reg);
    this._client.unSubscribe(reg, listener);
    return this;
  }

  publish(reg) {
    this.changeReg(reg);
    this._client.publish(reg);
    return this;
  }

  unPublish(reg) {
    this.changeReg(reg);
    this._client.unPublish(reg);
    return this;
  }

  register(reg) {
    this.changeReg(reg);
    this._client.publish(reg);
    return this;
  }

  unRegister(reg) {
    this.changeReg(reg);
    this._client.unPublish(reg);
    return this;
  }

  // 对 reg 做一个转换
  changeReg(reg) {
    // 如果 interfaceName 和 dataId 同时存在, dataId 会被覆盖
    if (reg.interfaceName) {
      reg.dataId = reg.interfaceName + ':' + reg.version + '@DEFAULT';
    }
    if (reg.group) {
      reg.groupId = reg.group;
    }

    if (reg.url) {
      reg.publishData = reg.url;
    }

    if (reg.group) {
      reg.groupId = reg.group;
      delete reg.group;
    }
  }
}

module.exports = APIClient;
